-- ---------------------------------------------------------------------------------------------
-- 1. Tables.
-- ---------------------------------------------------------------------------------------------
create table if not exists private.titan_club_matches (
  id uuid primary key default gen_random_uuid(),
  format text not null check (format in ('cooperation', 'versus')),
  host_club uuid not null references private.titan_clubs(id) on delete cascade,
  guest_club uuid references private.titan_clubs(id) on delete set null,
  code text unique check (code ~ '^[A-Z2-9]{8}$'),
  pace text not null check (pace in ('douce', 'reguliere', 'soutenue')),
  weeks integer not null check (weeks in (1, 2)),
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  join_until timestamptz not null,
  status text not null default 'proposed' check (status in ('proposed', 'accepted', 'refused', 'expired', 'cancelled', 'abandoned', 'closed')),
  stopped_by text check (stopped_by in ('host', 'guest')),
  stopped_at timestamptz,
  ended_at timestamptz,
  summary jsonb,
  created_by uuid references auth.users(id) on delete set null,
  answered_by uuid references auth.users(id) on delete set null,
  answered_at timestamptz,
  created_at timestamptz not null default now(),
  check (ends_at > starts_at and join_until > starts_at and join_until <= ends_at),
  check (guest_club is null or guest_club <> host_club),
  check (format <> 'versus' or weeks = 2),
  check ((status = 'proposed') = (code is not null))
);
create unique index if not exists titan_club_matches_host_open_uniq on private.titan_club_matches (host_club) where status in ('proposed', 'accepted');
create unique index if not exists titan_club_matches_guest_open_uniq on private.titan_club_matches (guest_club) where status = 'accepted';
create index if not exists titan_club_matches_guest_idx on private.titan_club_matches (guest_club, created_at desc);
create index if not exists titan_club_matches_host_idx on private.titan_club_matches (host_club, created_at desc);

create table if not exists private.titan_club_match_members (
  match_id uuid not null references private.titan_club_matches(id) on delete cascade,
  club_id uuid not null,
  user_id uuid not null references auth.users(id) on delete cascade,
  joined_at timestamptz not null default now(),
  left_at timestamptz,
  final_days integer,
  final_share integer,
  clear boolean,
  again boolean,
  answered_at timestamptz,
  primary key (match_id, user_id)
);
create index if not exists titan_club_match_members_user_idx on private.titan_club_match_members (user_id);
create index if not exists titan_club_match_members_side_idx on private.titan_club_match_members (match_id, club_id);

alter table private.titan_club_matches enable row level security;
alter table private.titan_club_match_members enable row level security;
revoke all on private.titan_club_matches, private.titan_club_match_members from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- 2. The measure: participation range, share, active days.
-- ---------------------------------------------------------------------------------------------
create or replace function private.titan_club_match_code()
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare v_chars constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; v_code text; i integer;
begin
  loop
    v_code := '';
    for i in 1..8 loop v_code := v_code || substr(v_chars, 1 + floor(random() * length(v_chars))::integer, 1); end loop;
    exit when not exists (select 1 from private.titan_club_matches where code = v_code);
  end loop;
  return v_code;
end;
$function$;
revoke all on function private.titan_club_match_code() from public, anon, authenticated;

-- The time a participant takes part: from their arrival (or the start) to their departure (or the end, or the stop).
create or replace function private.titan_club_match_range(p_match uuid, p_user uuid)
returns tstzrange
language sql
stable
security definer
set search_path = ''
as $$
  select case when greatest(x.starts_at, m.joined_at) < least(x.ends_at, coalesce(x.stopped_at, 'infinity'::timestamptz), coalesce(m.left_at, 'infinity'::timestamptz))
              then tstzrange(greatest(x.starts_at, m.joined_at), least(x.ends_at, coalesce(x.stopped_at, 'infinity'::timestamptz), coalesce(m.left_at, 'infinity'::timestamptz)), '[)')
              else 'empty'::tstzrange end
    from private.titan_club_matches x join private.titan_club_match_members m on m.match_id = x.id
   where x.id = p_match and m.user_id = p_user;
$$;
revoke all on function private.titan_club_match_range(uuid, uuid) from public, anon, authenticated;

-- A participant's share: active days per week of the pace × weeks of participation, rounded up — prorated to the second as a part of
-- the whole meeting, so that a full participant's share is exactly pace × weeks even in a week that crosses a change of time.
create or replace function private.titan_club_match_share(p_match uuid, p_user uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(ceil(round(private.titan_club_season_per_week(x.pace) * x.weeks
           * coalesce(extract(epoch from upper(r.rng) - lower(r.rng)), 0) / extract(epoch from x.ends_at - x.starts_at), 6))::integer, 0)
    from private.titan_club_matches x cross join lateral (select private.titan_club_match_range(p_match, p_user) as rng) r
   where x.id = p_match;
$$;
revoke all on function private.titan_club_match_share(uuid, uuid) from public, anon, authenticated;

-- Active days of a participant as of p_asof: confirmed sessions dated within the participation and before p_asof, recorded after the
-- participation began and before p_asof; a day counts with 12 counted minutes (90 a day at most).
create or replace function private.titan_club_match_days(p_match uuid, p_user uuid, p_asof timestamptz)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select count(*)::integer from (
    select x.day
      from (select private.titan_club_match_range(p_match, p_user) * tstzrange('-infinity', p_asof, '[)') as clip) c
      cross join lateral private.titan_confirmed_sessions(p_user, lower(c.clip), upper(c.clip), lower(c.clip)) x
      join public.training_logs l on l.id = x.log_id and l.created_at < p_asof
     where not isempty(c.clip)
     group by x.day
    having least(90, sum(x.effort_minutes)) >= 12) d;
$$;
revoke all on function private.titan_club_match_days(uuid, uuid, timestamptz) from public, anon, authenticated;

-- The moment every shared score is computed at: the last Paris midnight while the meeting runs (nobody sees when a member trains),
-- the end (or the stop) once it is over.
create or replace function private.titan_club_match_asof(p_match uuid)
returns timestamptz
language sql
stable
security definer
set search_path = ''
as $$
  select case when now() >= least(x.ends_at, coalesce(x.stopped_at, 'infinity'::timestamptz)) then least(x.ends_at, coalesce(x.stopped_at, 'infinity'::timestamptz))
              else greatest(x.starts_at, (date_trunc('day', now() at time zone 'Europe/Paris')) at time zone 'Europe/Paris') end
    from private.titan_club_matches x where x.id = p_match;
$$;
revoke all on function private.titan_club_match_asof(uuid) from public, anon, authenticated;

-- One club's side as of p_asof: participants still in, counted total (each up to their share), goal (sum of the shares), and the rate,
-- which exists only from 3 participants still in.
create or replace function private.titan_club_match_side(p_match uuid, p_club uuid, p_asof timestamptz)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with m as (
    select mm.user_id, mm.left_at, private.titan_club_match_share(p_match, mm.user_id) as share,
           private.titan_club_match_days(p_match, mm.user_id, p_asof) as days
      from private.titan_club_match_members mm where mm.match_id = p_match and mm.club_id = p_club),
  t as (select count(*) filter (where m.left_at is null)::integer as participants, coalesce(sum(least(m.days, m.share)), 0)::integer as total,
               coalesce(sum(m.share), 0)::integer as target from m)
  select jsonb_build_object('club', p_club, 'name', (select c.name from private.titan_clubs c where c.id = p_club),
           'participants', t.participants, 'total', t.total, 'target', t.target, 'scored', t.participants >= 3 and t.target > 0,
           'rate', case when t.participants >= 3 and t.target > 0 then floor(100.0 * t.total / t.target)::integer end)
    from t;
$$;
revoke all on function private.titan_club_match_side(uuid, uuid, timestamptz) from public, anon, authenticated;

-- The full score as of p_asof (internal): both sides, the common score (cooperation) or who leads (comparison).
create or replace function private.titan_club_match_score(p_match uuid, p_asof timestamptz)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare x private.titan_club_matches%rowtype; h jsonb; g jsonb; v_common integer; v_lead text;
begin
  select * into x from private.titan_club_matches where id = p_match;
  if x.id is null or x.guest_club is null then return null; end if;
  h := private.titan_club_match_side(p_match, x.host_club, p_asof);
  g := private.titan_club_match_side(p_match, x.guest_club, p_asof);
  if (h->>'scored')::boolean and (g->>'scored')::boolean then
    v_common := floor(((h->>'rate')::integer + (g->>'rate')::integer) / 2.0)::integer;
    v_lead := case when abs((h->>'rate')::integer - (g->>'rate')::integer) < 5 then 'tie'
                   when (h->>'rate')::integer > (g->>'rate')::integer then 'host' else 'guest' end;
  end if;
  return jsonb_build_object('asOf', p_asof, 'host', h, 'guest', g,
    'common', case when x.format = 'cooperation' then v_common end,
    'reached', case when x.format = 'cooperation' and v_common is not null then v_common >= 60 end,
    'lead', case when x.format = 'versus' then v_lead end);
end;
$function$;
revoke all on function private.titan_club_match_score(uuid, timestamptz) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- 3. Lifecycle: settle, touch, what a member reads.
-- ---------------------------------------------------------------------------------------------
-- Freezes the recap once (the row is locked by the caller). p_status 'closed' (at the end) or 'abandoned' (stopped while running).
create or replace function private.titan_club_match_settle(p_match uuid, p_status text, p_by text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $function$
declare x private.titan_club_matches%rowtype; v jsonb; v_at timestamptz;
begin
  select * into x from private.titan_club_matches where id = p_match;
  v_at := least(x.ends_at, coalesce(x.stopped_at, 'infinity'::timestamptz));
  update private.titan_club_match_members m set final_days = least(private.titan_club_match_days(p_match, m.user_id, v_at), private.titan_club_match_share(p_match, m.user_id)),
         final_share = private.titan_club_match_share(p_match, m.user_id)
   where m.match_id = p_match;
  v := private.titan_club_match_score(p_match, v_at);
  update private.titan_club_matches set status = p_status, ended_at = case when p_status = 'closed' then x.ends_at else now() end,
         stopped_by = coalesce(p_by, stopped_by),
         summary = case when p_status = 'abandoned' then jsonb_build_object('phase', 'abandoned', 'format', x.format, 'pace', x.pace, 'weeks', x.weeks,
                          'startsAt', x.starts_at, 'endsAt', x.ends_at, 'stoppedAt', x.stopped_at,
                          'host', jsonb_build_object('name', v->'host'->'name'), 'guest', jsonb_build_object('name', v->'guest'->'name'))
                        else jsonb_build_object('phase', case when (v->'host'->>'scored')::boolean and (v->'guest'->>'scored')::boolean then 'closed' else 'short' end,
                          'format', x.format, 'pace', x.pace, 'weeks', x.weeks, 'startsAt', x.starts_at, 'endsAt', x.ends_at,
                          'host', v->'host', 'guest', v->'guest', 'common', v->'common', 'reached', v->'reached', 'lead', v->'lead') end
   where id = p_match;
end;
$function$;
revoke all on function private.titan_club_match_settle(uuid, text, text) from public, anon, authenticated;

-- Under the row lock: a proposal not accepted before the start expires; a meeting whose end has come is settled. Idempotent.
create or replace function private.titan_club_match_touch(p_match uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $function$
declare x private.titan_club_matches%rowtype;
begin
  select * into x from private.titan_club_matches where id = p_match for update;
  if x.id is null then return; end if;
  if x.status = 'proposed' and now() >= x.starts_at then
    update private.titan_club_matches set status = 'expired', code = null, ended_at = x.starts_at,
           summary = jsonb_build_object('phase', 'expired', 'format', x.format, 'startsAt', x.starts_at) where id = p_match;
  elsif x.status = 'accepted' and now() >= x.ends_at then
    perform private.titan_club_match_settle(p_match, 'closed');
  end if;
end;
$function$;
revoke all on function private.titan_club_match_touch(uuid) from public, anon, authenticated;

-- The open meeting of a club (proposed or accepted, as host or guest).
create or replace function private.titan_club_match_open(p_club uuid)
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select id from private.titan_club_matches
   where (host_club = p_club and status in ('proposed', 'accepted')) or (guest_club = p_club and status = 'accepted')
   order by created_at desc limit 1;
$$;
revoke all on function private.titan_club_match_open(uuid) from public, anon, authenticated;

-- What a member of p_club reads of the open meeting: their club in full totals (from 3), the other club's name, participants and rate
-- only, the score as of the last midnight, their own days live, and the actions open to them. A proposal is read by the host's
-- administrators only (with its code).
create or replace function private.titan_club_match_view(p_match uuid, p_club uuid, p_viewer uuid, p_role text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  x private.titan_club_matches%rowtype; v jsonb; us jsonb; them jsonb; v_side text; v_phase text; me jsonb; v_can jsonb := '[]'::jsonb;
  m private.titan_club_match_members%rowtype; v_suspended boolean; v_lead text;
begin
  select * into x from private.titan_club_matches where id = p_match;
  if x.id is null then return null; end if;
  v_side := case when x.host_club = p_club then 'host' else 'guest' end;
  if x.status = 'proposed' then
    if v_side <> 'host' or p_role <> 'admin' then return null; end if;
    return jsonb_build_object('id', x.id, 'format', x.format, 'pace', x.pace, 'perWeek', private.titan_club_season_per_week(x.pace), 'weeks', x.weeks,
      'startsAt', x.starts_at, 'endsAt', x.ends_at, 'joinUntil', x.join_until, 'phase', 'proposed', 'side', 'host', 'code', x.code,
      'us', jsonb_build_object('name', (select c.name from private.titan_clubs c where c.id = p_club)), 'them', null,
      'threshold', 3, 'goal', 60, 'tieMargin', 5, 'can', '["stop"]'::jsonb);
  end if;
  v_phase := case when now() < x.starts_at then 'upcoming' when now() < x.ends_at then 'running' else 'ended' end;
  v := private.titan_club_match_score(p_match, private.titan_club_match_asof(p_match));
  us := v -> v_side;
  them := v -> (case when v_side = 'host' then 'guest' else 'host' end);
  -- One's own club: totals from the threshold. The other club: a name, a number of participants and a rate; nothing else, ever.
  us := jsonb_build_object('name', us->'name', 'participants', us->'participants', 'scored', us->'scored', 'rate', us->'rate',
          'total', case when (us->>'scored')::boolean then us->'total' end, 'target', case when (us->>'scored')::boolean then us->'target' end);
  them := jsonb_build_object('name', them->'name', 'participants', them->'participants', 'scored', them->'scored', 'rate', them->'rate');
  v_lead := v->>'lead';
  select * into m from private.titan_club_match_members where match_id = p_match and user_id = p_viewer;
  if m.user_id is not null then
    me := jsonb_build_object('status', case when m.left_at is not null then 'left' else 'active' end, 'club', m.club_id,
      'days', least(private.titan_club_match_days(p_match, p_viewer, now()), private.titan_club_match_share(p_match, p_viewer)),
      'share', private.titan_club_match_share(p_match, p_viewer));
  end if;
  v_suspended := exists (select 1 from public.profiles p where p.id = p_viewer and coalesce(p.is_suspended, false));
  if v_phase in ('upcoming', 'running') then
    if m.user_id is null and now() < x.join_until and not v_suspended then v_can := v_can || '["join"]'::jsonb; end if;
    if m.user_id is not null and m.left_at is null and m.club_id = p_club then v_can := v_can || '["leave"]'::jsonb; end if;
    if p_role = 'admin' then v_can := v_can || '["stop"]'::jsonb; end if;
  end if;
  return jsonb_build_object('id', x.id, 'format', x.format, 'pace', x.pace, 'perWeek', private.titan_club_season_per_week(x.pace), 'weeks', x.weeks,
    'startsAt', x.starts_at, 'endsAt', x.ends_at, 'joinUntil', x.join_until, 'phase', v_phase, 'side', v_side, 'asOf', v->'asOf',
    'threshold', 3, 'goal', 60, 'tieMargin', 5, 'us', us, 'them', them,
    'common', v->'common', 'reached', v->'reached',
    'lead', case when v_lead is null then null when v_lead = 'tie' then 'tie' when v_lead = v_side then 'us' else 'them' end,
    'me', me, 'can', v_can, 'suspended', v_suspended);
end;
$function$;
revoke all on function private.titan_club_match_view(uuid, uuid, uuid, text) from public, anon, authenticated;

-- The frozen recap, as a member of p_club reads it: totals by club only; one's own part.
create or replace function private.titan_club_match_report(p_match uuid, p_club uuid, p_viewer uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare x private.titan_club_matches%rowtype; s jsonb; v_side text; v_other text; us jsonb; them jsonb; m private.titan_club_match_members%rowtype;
begin
  select * into x from private.titan_club_matches where id = p_match;
  if x.id is null or x.summary is null then return null; end if;
  s := x.summary;
  v_side := case when x.host_club = p_club then 'host' else 'guest' end;
  v_other := case when v_side = 'host' then 'guest' else 'host' end;
  us := s -> v_side; them := s -> v_other;
  if us is not null and us <> 'null'::jsonb then
    us := jsonb_build_object('name', us->'name', 'participants', us->'participants', 'scored', us->'scored', 'rate', us->'rate',
            'total', case when (us->>'scored')::boolean then us->'total' end, 'target', case when (us->>'scored')::boolean then us->'target' end);
  end if;
  if them is not null and them <> 'null'::jsonb then
    them := jsonb_build_object('name', coalesce(them->'name', to_jsonb((select c.name from private.titan_clubs c where c.id = case when v_other = 'host' then x.host_club else x.guest_club end))),
            'participants', them->'participants', 'scored', them->'scored', 'rate', them->'rate');
  elsif x.guest_club is not null then
    them := jsonb_build_object('name', (select c.name from private.titan_clubs c where c.id = case when v_other = 'host' then x.host_club else x.guest_club end));
  end if;
  select * into m from private.titan_club_match_members where match_id = p_match and user_id = p_viewer;
  return jsonb_build_object('id', x.id, 'phase', s->'phase', 'format', x.format, 'pace', x.pace, 'weeks', x.weeks, 'startsAt', x.starts_at,
    'endsAt', x.ends_at, 'stoppedAt', x.stopped_at, 'endedAt', x.ended_at, 'side', v_side, 'threshold', 3, 'goal', 60, 'tieMargin', 5,
    'stoppedBy', case when x.stopped_by is null then null when x.stopped_by = v_side then 'us' else 'them' end,
    'us', us, 'them', them, 'common', s->'common', 'reached', s->'reached',
    'lead', case when s->>'lead' is null then null when s->>'lead' = 'tie' then 'tie' when s->>'lead' = v_side then 'us' else 'them' end,
    'me', case when m.user_id is not null then jsonb_build_object('days', m.final_days, 'share', m.final_share, 'left', m.left_at is not null,
            'answered', m.answered_at is not null) end,
    'can', case when m.user_id is not null and m.answered_at is null and x.status in ('closed', 'abandoned') then '["feedback"]'::jsonb else '[]'::jsonb end);
end;
$function$;
revoke all on function private.titan_club_match_report(uuid, uuid, uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- 4. The API: read, preview a code, act.
-- ---------------------------------------------------------------------------------------------
create or replace function public.titan_club_match_v1(p_club uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
set statement_timeout = '8s'
as $function$
declare v_uid uuid := auth.uid(); v_role text; v_open uuid; v_last uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  select m.role into v_role from private.titan_club_members m join private.titan_clubs c on c.id = m.club_id
   where m.club_id = p_club and m.user_id = v_uid and c.archived_at is null;
  if v_role is null then raise exception 'CLUB_NOT_FOUND' using errcode = 'P0002'; end if;
  v_open := private.titan_club_match_open(p_club);
  if v_open is not null then
    perform private.titan_club_match_touch(v_open);
    v_open := private.titan_club_match_open(p_club);
  end if;
  -- The last recap of the 60 days: a meeting both clubs agreed to (closed, abandoned, cancelled after acceptance) for every member;
  -- a proposal that was refused, expired or withdrawn for the host's administrators only.
  select x.id into v_last from private.titan_club_matches x
   where x.ended_at > now() - interval '60 days' and x.summary is not null
     and ((x.status in ('closed', 'abandoned') and (x.host_club = p_club or x.guest_club = p_club))
       or (x.status = 'cancelled' and x.guest_club is not null and (x.host_club = p_club or x.guest_club = p_club))
       or (x.status in ('refused', 'expired', 'cancelled') and x.host_club = p_club and v_role = 'admin'))
   order by x.ended_at desc, x.created_at desc limit 1;
  return jsonb_build_object('club', p_club, 'role', case when v_role = 'admin' then 'organizer' else 'member' end,
    'current', case when v_open is not null then private.titan_club_match_view(v_open, p_club, v_uid, v_role) end,
    'last', case when v_last is not null then private.titan_club_match_report(v_last, p_club, v_uid) end,
    'canPropose', v_role = 'admin' and v_open is null,
    'formats', case when private.titan_flag_on('screens.club_match_versus') then '["cooperation", "versus"]'::jsonb else '["cooperation"]'::jsonb end);
end;
$function$;

-- An administrator of p_club reads a proposal from its code before answering. Never an error for a wrong code (null instead), so that the
-- limiter's count is kept: 20 lookups per account and hour.
create or replace function public.titan_club_match_preview_v1(p_club uuid, p_code text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $function$
declare v_uid uuid := auth.uid(); v_code text := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g')); x private.titan_club_matches%rowtype;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  if not private.titan_flag_on('screens.club_match') then raise exception 'FEATURE_DISABLED' using errcode = '42501'; end if;
  if not exists (select 1 from private.titan_club_members m join private.titan_clubs c on c.id = m.club_id
                  where m.club_id = p_club and m.user_id = v_uid and c.archived_at is null) then raise exception 'CLUB_NOT_FOUND' using errcode = 'P0002'; end if;
  if not exists (select 1 from private.titan_club_members m where m.club_id = p_club and m.user_id = v_uid and m.role = 'admin') then
    raise exception 'CLUB_ADMIN_REQUIRED' using errcode = '42501';
  end if;
  perform private.titan_rate_limit(v_uid, 'club_match_code', 20);
  select * into x from private.titan_club_matches where code = v_code and status = 'proposed' and starts_at > now()
     and exists (select 1 from private.titan_clubs c where c.id = host_club and c.archived_at is null);
  if x.id is null then return null; end if;
  return jsonb_build_object('id', x.id, 'self', x.host_club = p_club, 'host', (select c.name from private.titan_clubs c where c.id = x.host_club),
    'format', x.format, 'pace', x.pace, 'perWeek', private.titan_club_season_per_week(x.pace), 'weeks', x.weeks, 'startsAt', x.starts_at,
    'endsAt', x.ends_at, 'joinUntil', x.join_until, 'threshold', 3, 'goal', 60, 'tieMargin', 5);
end;
$function$;

create or replace function public.titan_club_match_act_v1(p_club uuid, p_action text, p_format text default null, p_pace text default null,
  p_weeks integer default null, p_starts_on date default null, p_match uuid default null, p_clear boolean default null, p_again boolean default null)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $function$
declare
  v_uid uuid := auth.uid();
  v_role text;
  x private.titan_club_matches%rowtype;
  m private.titan_club_match_members%rowtype;
  v_today date := (now() at time zone 'Europe/Paris')::date;
  v_start timestamptz;
  v_id uuid;
  v_side text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  if p_action is null or p_action not in ('propose', 'accept', 'refuse', 'join', 'leave', 'stop', 'feedback') then raise exception 'MATCH_INVALID' using errcode = '22023'; end if;
  if p_action in ('propose', 'accept', 'join') and not private.titan_flag_on('screens.club_match') then raise exception 'FEATURE_DISABLED' using errcode = '42501'; end if;
  select cm.role into v_role from private.titan_club_members cm join private.titan_clubs c on c.id = cm.club_id
   where cm.club_id = p_club and cm.user_id = v_uid and c.archived_at is null;
  if v_role is null then raise exception 'CLUB_NOT_FOUND' using errcode = 'P0002'; end if;
  if p_action in ('propose', 'accept', 'refuse', 'stop') and v_role <> 'admin' then raise exception 'CLUB_ADMIN_REQUIRED' using errcode = '42501'; end if;
  if p_action in ('propose', 'accept', 'join') and exists (select 1 from public.profiles p where p.id = v_uid and coalesce(p.is_suspended, false)) then
    raise exception 'ACCOUNT_SUSPENDED' using errcode = '42501';
  end if;

  if p_action = 'propose' then
    if not private.titan_can_vote(v_uid) then raise exception 'NOT_ELIGIBLE' using errcode = '42501'; end if;
    perform private.titan_rate_limit(v_uid, 'club_match', 10);
    if p_format is null or p_format not in ('cooperation', 'versus') or p_pace is null or p_pace not in ('douce', 'reguliere', 'soutenue')
       or p_weeks is null or p_weeks not between 1 and 2 or p_starts_on is null or p_starts_on < v_today + 1 or p_starts_on > v_today + 28 then
      raise exception 'MATCH_INVALID' using errcode = '22023';
    end if;
    if p_format = 'versus' and not private.titan_flag_on('screens.club_match_versus') then raise exception 'VERSUS_CLOSED' using errcode = '42501'; end if;
    if p_format = 'versus' and p_weeks <> 2 then raise exception 'MATCH_INVALID' using errcode = '22023'; end if;
    perform 1 from private.titan_clubs where id = p_club for update;
    v_id := private.titan_club_match_open(p_club);
    if v_id is not null then perform private.titan_club_match_touch(v_id); end if;
    if private.titan_club_match_open(p_club) is not null then raise exception 'MATCH_OPEN' using errcode = '22023'; end if;
    v_start := p_starts_on::timestamp at time zone 'Europe/Paris';
    insert into private.titan_club_matches (format, host_club, code, pace, weeks, starts_at, ends_at, join_until, created_by)
    -- Paris midnights (a week that crosses a change of time is still seven Paris days).
    values (p_format, p_club, private.titan_club_match_code(), p_pace, p_weeks, v_start, (p_starts_on + p_weeks * 7)::timestamp at time zone 'Europe/Paris',
            (p_starts_on + 2)::timestamp at time zone 'Europe/Paris', v_uid);
    return public.titan_club_match_v1(p_club);
  end if;

  if p_action in ('accept', 'refuse') then
    select * into x from private.titan_club_matches where id = p_match;
    if x.id is null or x.status <> 'proposed' then raise exception 'MATCH_CODE' using errcode = '22023'; end if;
    if x.host_club = p_club then raise exception 'MATCH_SELF' using errcode = '22023'; end if;
    -- Both clubs are locked in a fixed order: two answers to the same proposal, or an answer and a withdrawal, are serialised.
    perform 1 from private.titan_clubs where id in (x.host_club, p_club) order by id for update;
    perform private.titan_club_match_touch(x.id);
    select * into x from private.titan_club_matches where id = p_match;
    if x.status = 'expired' then raise exception 'MATCH_STARTED' using errcode = '22023'; end if;
    if x.status <> 'proposed' then raise exception 'MATCH_CODE' using errcode = '22023'; end if;
    if p_action = 'refuse' then
      update private.titan_club_matches set status = 'refused', code = null, guest_club = p_club, answered_by = v_uid, answered_at = now(), ended_at = now(),
             summary = jsonb_build_object('phase', 'refused', 'format', x.format, 'startsAt', x.starts_at) where id = x.id;
      return public.titan_club_match_v1(p_club);
    end if;
    if x.created_by = v_uid then raise exception 'MATCH_SAME_ORGANISER' using errcode = '22023'; end if;
    if x.format = 'versus' and not private.titan_flag_on('screens.club_match_versus') then raise exception 'VERSUS_CLOSED' using errcode = '42501'; end if;
    v_id := private.titan_club_match_open(p_club);
    if v_id is not null then perform private.titan_club_match_touch(v_id); end if;
    if private.titan_club_match_open(p_club) is not null then raise exception 'MATCH_OPEN' using errcode = '22023'; end if;
    update private.titan_club_matches set status = 'accepted', code = null, guest_club = p_club, answered_by = v_uid, answered_at = now() where id = x.id;
    return public.titan_club_match_v1(p_club);
  end if;

  if p_action = 'feedback' then
    if p_clear is null or p_again is null then raise exception 'MATCH_INVALID' using errcode = '22023'; end if;
    update private.titan_club_match_members mm set clear = p_clear, again = p_again, answered_at = now()
      from private.titan_club_matches y
     where y.id = mm.match_id and mm.user_id = v_uid and mm.club_id = p_club and mm.answered_at is null
       and y.status in ('closed', 'abandoned') and y.ended_at > now() - interval '60 days'
       and y.id = (select z.id from private.titan_club_matches z where (z.host_club = p_club or z.guest_club = p_club)
                    and z.status in ('closed', 'abandoned', 'cancelled') and z.ended_at > now() - interval '60 days' order by z.ended_at desc, z.created_at desc limit 1);
    if not found then raise exception 'MATCH_NOT_IN' using errcode = '22023'; end if;
    return public.titan_club_match_v1(p_club);
  end if;

  -- join, leave, stop act on the club's open meeting, under both clubs' locks.
  v_id := private.titan_club_match_open(p_club);
  if v_id is null then raise exception 'MATCH_NOT_FOUND' using errcode = 'P0002'; end if;
  select * into x from private.titan_club_matches where id = v_id;
  perform 1 from private.titan_clubs where id in (x.host_club, coalesce(x.guest_club, x.host_club)) order by id for update;
  perform private.titan_club_match_touch(v_id);
  select * into x from private.titan_club_matches where id = v_id for update;
  if x.status not in ('proposed', 'accepted') then raise exception 'MATCH_ENDED' using errcode = '22023'; end if;
  v_side := case when x.host_club = p_club then 'host' else 'guest' end;
  select * into m from private.titan_club_match_members where match_id = x.id and user_id = v_uid;

  if p_action = 'join' then
    if x.status <> 'accepted' then raise exception 'MATCH_NOT_FOUND' using errcode = 'P0002'; end if;
    if m.user_id is not null and m.left_at is not null then raise exception 'MATCH_LEFT' using errcode = '22023'; end if;
    if m.user_id is null then
      if now() >= x.join_until then raise exception 'MATCH_JOIN_CLOSED' using errcode = '22023'; end if;
      perform private.titan_rate_limit(v_uid, 'club_match_join', 30);
      insert into private.titan_club_match_members (match_id, club_id, user_id) values (x.id, p_club, v_uid);
    end if;
  elsif p_action = 'leave' then
    if m.user_id is null or m.left_at is not null or m.club_id <> p_club then raise exception 'MATCH_NOT_IN' using errcode = '22023'; end if;
    update private.titan_club_match_members set left_at = now() where match_id = x.id and user_id = v_uid;
  elsif p_action = 'stop' then
    if x.status = 'proposed' then
      if v_side <> 'host' then raise exception 'MATCH_NOT_FOUND' using errcode = 'P0002'; end if;
      update private.titan_club_matches set status = 'cancelled', code = null, stopped_by = 'host', stopped_at = now(), ended_at = now(),
             summary = jsonb_build_object('phase', 'cancelled', 'format', x.format, 'startsAt', x.starts_at, 'withdrawn', true) where id = x.id;
    elsif now() < x.starts_at then
      update private.titan_club_matches set status = 'cancelled', stopped_by = v_side, stopped_at = now(), ended_at = now(),
             summary = jsonb_build_object('phase', 'cancelled', 'format', x.format, 'startsAt', x.starts_at,
               'host', jsonb_build_object('name', (select c.name from private.titan_clubs c where c.id = x.host_club)),
               'guest', jsonb_build_object('name', (select c.name from private.titan_clubs c where c.id = x.guest_club))) where id = x.id;
    else
      update private.titan_club_matches set stopped_at = now() where id = x.id;
      perform private.titan_club_match_settle(x.id, 'abandoned', v_side);
    end if;
  end if;
  return public.titan_club_match_v1(p_club);
end;
$function$;
revoke all on function public.titan_club_match_v1(uuid), public.titan_club_match_preview_v1(uuid, text),
  public.titan_club_match_act_v1(uuid, text, text, text, integer, date, uuid, boolean, boolean) from public, anon;
grant execute on function public.titan_club_match_v1(uuid), public.titan_club_match_preview_v1(uuid, text),
  public.titan_club_match_act_v1(uuid, text, text, text, integer, date, uuid, boolean, boolean) to authenticated;

-- Leaving the club, or being removed from it, leaves its open meeting; acquired days stay with the club, the share shrinks to the time spent.
create or replace function private.titan_club_match_member_left()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
begin
  -- An erased account takes its participation with it (cascade): nothing to end.
  if not exists (select 1 from auth.users u where u.id = old.user_id) then return old; end if;
  update private.titan_club_match_members mm set left_at = now()
    from private.titan_club_matches x
   where x.id = mm.match_id and x.status = 'accepted' and mm.club_id = old.club_id and mm.user_id = old.user_id and mm.left_at is null;
  return old;
end;
$function$;
revoke all on function private.titan_club_match_member_left() from public, anon, authenticated;
drop trigger if exists titan_club_members_match on private.titan_club_members;
create trigger titan_club_members_match after delete on private.titan_club_members
  for each row execute function private.titan_club_match_member_left();

-- ---------------------------------------------------------------------------------------------
-- 5. The account export (cumulative): one's own participations and answers, the meetings one proposed or answered; never another member.
-- ---------------------------------------------------------------------------------------------
create or replace function private.titan_social_export_v1(p_uid uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'friendInvites', coalesce((select jsonb_agg(jsonb_build_object('created_at', i.created_at, 'expires_at', i.expires_at, 'revoked_at', i.revoked_at,
                       'used_at', i.used_at) order by i.created_at) from private.titan_friend_invites i where i.created_by = p_uid), '[]'::jsonb),
    'cordeeTitles', coalesce((select jsonb_agg(jsonb_build_object('route', t.route, 'challenge_id', t.challenge_id, 'earned_at', t.earned_at)
                       order by t.earned_at, t.route) from private.titan_cordee_titles t where t.user_id = p_uid), '[]'::jsonb),
    'cordeeRelays', coalesce((select jsonb_agg(x.j order by x.at) from (
        select r.opened_at as at, jsonb_build_object('challenge_id', r.challenge_id, 'step', r.step, 'action', 'transmit', 'at', r.opened_at,
               'log_id', r.opened_log, 'day', r.opened_day) as j from private.titan_cordee_relays r where r.opened_by = p_uid
        union all
        select r.confirmed_at, jsonb_build_object('challenge_id', r.challenge_id, 'step', r.step, 'action', 'confirm', 'at', r.confirmed_at,
               'log_id', r.confirmed_log, 'day', r.confirmed_day) from private.titan_cordee_relays r where r.confirmed_by = p_uid) x), '[]'::jsonb),
    'cordeeRelayTurns', coalesce((select jsonb_agg(jsonb_build_object('challenge_id', t.challenge_id, 'kind', t.kind,
        'role', case when t.kind = 'take' then 'took' when t.from_user = p_uid then 'offered' when t.accepted_by = p_uid then 'accepted' else 'offered_to_me' end,
        'open', case when t.kind = 'handover' then t.to_user is null end, 'status', t.status, 'at', t.created_at, 'expires_at', t.expires_at,
        'resolved_at', t.resolved_at) order by t.created_at)
      from private.titan_cordee_relay_turns t where t.from_user = p_uid or t.to_user = p_uid or t.accepted_by = p_uid), '[]'::jsonb),
    'cordeeSuites', coalesce((select jsonb_agg(x.j order by x.at) from (
        select s.created_at as at, jsonb_build_object('from_id', s.from_id, 'role', 'proposed', 'route', s.route, 'pace', s.pace, 'days', s.days,
               'status', s.status, 'at', s.created_at, 'started_id', s.started_id) as j
          from private.titan_cordee_suites s where s.proposed_by = p_uid
        union all
        select a.answered_at, jsonb_build_object('from_id', s.from_id, 'role', 'answered', 'answer', a.answer, 'route', s.route, 'pace', s.pace,
               'days', s.days, 'at', a.answered_at)
          from private.titan_cordee_suite_answers a join private.titan_cordee_suites s on s.id = a.suite_id
         where a.user_id = p_uid and s.proposed_by is distinct from p_uid) x), '[]'::jsonb),
    'clubSeasons', coalesce((select jsonb_agg(x.j order by x.at) from (
        select s.created_at as at, jsonb_build_object('season_id', s.id, 'club_id', s.club_id, 'role', 'organised', 'title', s.title, 'pace', s.pace,
               'weeks', s.weeks, 'starts_at', s.starts_at, 'status', s.status, 'at', s.created_at) as j
          from private.titan_club_seasons s where s.created_by = p_uid
        union all
        select m.joined_at, jsonb_build_object('season_id', m.season_id, 'club_id', s.club_id, 'role', 'took_part', 'title', s.title, 'joined_at', m.joined_at,
               'left_at', m.left_at, 'final_days', m.final_days,
               'pauses', coalesce((select jsonb_agg(jsonb_build_object('paused_at', p.paused_at, 'resumed_at', p.resumed_at) order by p.paused_at)
                                     from private.titan_club_season_pauses p where p.season_id = m.season_id and p.user_id = p_uid), '[]'::jsonb))
          from private.titan_club_season_members m join private.titan_club_seasons s on s.id = m.season_id where m.user_id = p_uid) x), '[]'::jsonb),
    'clubMatches', coalesce((select jsonb_agg(x.j order by x.at) from (
        select y.created_at as at, jsonb_build_object('match_id', y.id, 'club_id', y.host_club, 'role', 'proposed', 'format', y.format, 'pace', y.pace,
               'weeks', y.weeks, 'starts_at', y.starts_at, 'status', y.status, 'at', y.created_at) as j
          from private.titan_club_matches y where y.created_by = p_uid
        union all
        select y.answered_at, jsonb_build_object('match_id', y.id, 'club_id', y.guest_club, 'role', case when y.status = 'refused' then 'refused' else 'accepted' end,
               'format', y.format, 'starts_at', y.starts_at, 'at', y.answered_at)
          from private.titan_club_matches y where y.answered_by = p_uid
        union all
        select m.joined_at, jsonb_build_object('match_id', m.match_id, 'club_id', m.club_id, 'role', 'took_part', 'format', y.format, 'joined_at', m.joined_at,
               'left_at', m.left_at, 'final_days', m.final_days, 'final_share', m.final_share, 'clear', m.clear, 'again', m.again, 'answered_at', m.answered_at)
          from private.titan_club_match_members m join private.titan_club_matches y on y.id = m.match_id where m.user_id = p_uid) x), '[]'::jsonb));
$$;
revoke all on function private.titan_social_export_v1(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- 6. The measure of the pilot: meetings completed, misunderstandings of the score, sides that want to play again. Counts only.
-- ---------------------------------------------------------------------------------------------
create or replace function private.titan_club_match_measure(p_since timestamptz default now() - interval '56 days')
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with y as (select * from private.titan_club_matches where created_at >= p_since),
  ended as (select * from y where y.status = 'closed'),
  ans as (select m.* from private.titan_club_match_members m join y on y.id = m.match_id where m.answered_at is not null),
  sides as (select a.match_id, a.club_id, count(*) as n, count(*) filter (where a.again) as again from ans a group by 1, 2)
  select jsonb_build_object('since', p_since,
    'proposed', (select count(*) from y),
    'accepted', (select count(*) from y where y.answered_at is not null and y.status <> 'refused'),
    'refused', (select count(*) from y where y.status = 'refused'),
    'expired', (select count(*) from y where y.status = 'expired'),
    'cancelled', (select count(*) from y where y.status = 'cancelled'),
    'abandoned', (select count(*) from y where y.status = 'abandoned'),
    'completed', (select count(*) from ended where ended.summary->>'phase' = 'closed'),
    'completedCooperation', (select count(*) from ended where ended.summary->>'phase' = 'closed' and ended.format = 'cooperation'),
    'reachedTogether', (select count(*) from ended where ended.summary->>'phase' = 'closed' and (ended.summary->>'reached')::boolean),
    'withoutResult', (select count(*) from ended where ended.summary->>'phase' = 'short'),
    'answers', (select count(*) from ans),
    'unclear', (select count(*) from ans where not ans.clear),
    'unclearShare', (select round(count(*) filter (where not ans.clear)::numeric / nullif(count(*), 0), 3) from ans),
    'sidesAnswering', (select count(*) from sides),
    'sidesAgain', (select count(*) from sides where sides.again * 2 > sides.n),
    'sidesAgainShare', (select round(count(*) filter (where sides.again * 2 > sides.n)::numeric / nullif(count(*), 0), 3) from sides),
    -- The gate for the comparative format: at least 5 cooperation meetings completed, 10 answers, and at most 1 answer in 5 unclear.
    'explainable', (select count(*) from ended where ended.summary->>'phase' = 'closed' and ended.format = 'cooperation') >= 5
                   and (select count(*) from ans) >= 10
                   and coalesce((select count(*) filter (where not ans.clear)::numeric / nullif(count(*), 0) from ans), 1) <= 0.2);
$$;
revoke all on function private.titan_club_match_measure(timestamptz) from public, anon, authenticated;
grant execute on function private.titan_club_match_measure(timestamptz) to service_role;

notify pgrst, 'reload schema';
-- <<< repository file
insert into supabase_migrations.schema_migrations (version, name) values ('20261130104500', 'club_match');
commit;
